import React, { useState, useEffect, useRef } from 'react';
import { Clock, CheckCircle, XCircle, AlertCircle, Search, Package, Zap, Eye, Filter, RefreshCw } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAuthStore } from '../stores/authStore';
import { scanAPI, adminAPI } from '../services/api';
import { playSuccessSound, playErrorSound } from '../utils/soundUtils';

const B2BPOPending = () => {
  const { user } = useAuthStore();
  const [activeTab, setActiveTab] = useState('pending');
  
  // Pending PO State
  const [poNumber, setPONumber] = useState('');
  const [pendingLoading, setPendingLoading] = useState(false);
  const [currentPOStatus, setCurrentPOStatus] = useState('');
  const [statusLoading, setStatusLoading] = useState(false);
  
  // Pending List State
  const [pendingList, setPendingList] = useState([]);
  const [pendingListLoading, setPendingListLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [dateFilter, setDateFilter] = useState('');
  
  // Approval State
  const [approvalLoading, setApprovalLoading] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');
  const [showRejectionModal, setShowRejectionModal] = useState(false);
  const [selectedPO, setSelectedPO] = useState(null);
  
  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);
  const itemsPerPage = 20;
  
  // Refs for input focus
  const poNumberInputRef = useRef(null);
  
  // Set document title
  useEffect(() => {
    document.title = 'B2B PO Pending - OneScan';
  }, []);
  
  // Focus on input when component mounts
  useEffect(() => {
    if (poNumberInputRef.current) {
      poNumberInputRef.current.focus();
    }
  }, [activeTab]);
  
  // Fetch pending list
  const fetchPendingList = async (page = 1, search = '', priority = 'all', date = '') => {
    try {
      setPendingListLoading(true);
      const params = new URLSearchParams({
        page: page.toString(),
        limit: itemsPerPage.toString(),
        search: search,
        priority: priority,
        date: date
      });
      
      const response = await adminAPI.get(`/b2b/pending?${params}`);
      
      setPendingList(response.data.pending_orders || []);
      setTotalPages(response.data.total_pages || 1);
      setTotalItems(response.data.total_items || 0);
    } catch (error) {
      console.error('Error fetching pending list:', error);
      toast.error('Failed to fetch pending orders');
    } finally {
      setPendingListLoading(false);
    }
  };
  
  // Handle PO approval
  const handlePOApproval = async (poId, action) => {
    try {
      setApprovalLoading(true);
      
      const requestData = {
        action: action,
        approved_by: user.username,
        approved_at: new Date().toISOString()
      };
      
      if (action === 'reject' && rejectionReason) {
        requestData.rejection_reason = rejectionReason;
      }
      
      const response = await adminAPI.put(`/b2b/pending/${poId}/approve`, requestData);
      
      if (response.data.success) {
        toast.success(`PO ${action === 'approve' ? 'approved' : 'rejected'} successfully!`);
        playSuccessSound();
        setShowRejectionModal(false);
        setRejectionReason('');
        setSelectedPO(null);
        fetchPendingList(currentPage, searchTerm, priorityFilter, dateFilter);
      } else {
        toast.error(response.data.message || `Failed to ${action} PO`);
        playErrorSound();
      }
    } catch (error) {
      console.error(`Error ${action}ing PO:`, error);
      toast.error(error.response?.data?.detail || error.message || `Failed to ${action} PO`);
      playErrorSound();
    } finally {
      setApprovalLoading(false);
    }
  };
  
  // Check PO status
  const checkPOStatus = async (poNumber) => {
    if (!poNumber.trim()) {
      toast.error('Please enter a PO number');
      return;
    }
    
    try {
      setStatusLoading(true);
      const response = await scanAPI.get(`/b2b/po-status/${poNumber.trim()}`);
      
      if (response.data) {
        setCurrentPOStatus(response.data);
        toast.success('PO status retrieved');
      } else {
        toast.error('PO not found');
      }
    } catch (error) {
      console.error('Error checking PO status:', error);
      toast.error(error.response?.data?.detail || error.message || 'Failed to check PO status');
    } finally {
      setStatusLoading(false);
    }
  };
  
  // Bulk approve POs
  const handleBulkApproval = async (action) => {
    const selectedPOs = pendingList.filter(po => po.selected);
    
    if (selectedPOs.length === 0) {
      toast.error('Please select POs to approve/reject');
      return;
    }
    
    try {
      setApprovalLoading(true);
      
      const response = await adminAPI.post('/b2b/pending/bulk-approve', {
        po_ids: selectedPOs.map(po => po.id),
        action: action,
        approved_by: user.username,
        approved_at: new Date().toISOString()
      });
      
      if (response.data.success) {
        toast.success(`${selectedPOs.length} POs ${action === 'approve' ? 'approved' : 'rejected'} successfully!`);
        playSuccessSound();
        fetchPendingList(currentPage, searchTerm, priorityFilter, dateFilter);
      } else {
        toast.error(response.data.message || `Failed to ${action} POs`);
        playErrorSound();
      }
    } catch (error) {
      console.error(`Error bulk ${action}ing POs:`, error);
      toast.error(error.response?.data?.detail || error.message || `Failed to ${action} POs`);
      playErrorSound();
    } finally {
      setApprovalLoading(false);
    }
  };
  
  // Toggle PO selection
  const togglePOSelection = (poId) => {
    setPendingList(prev => prev.map(po => 
      po.id === poId ? { ...po, selected: !po.selected } : po
    ));
  };
  
  // Select all POs
  const selectAllPOs = () => {
    setPendingList(prev => prev.map(po => ({ ...po, selected: true })));
  };
  
  // Deselect all POs
  const deselectAllPOs = () => {
    setPendingList(prev => prev.map(po => ({ ...po, selected: false })));
  };
  
  // Load data on component mount
  useEffect(() => {
    fetchPendingList();
  }, []);
  
  // Handle search
  const handleSearch = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchPendingList(1, searchTerm, priorityFilter, dateFilter);
  };
  
  // Handle filter change
  const handleFilterChange = () => {
    setCurrentPage(1);
    fetchPendingList(1, searchTerm, priorityFilter, dateFilter);
  };
  
  // Handle page change
  const handlePageChange = (page) => {
    setCurrentPage(page);
    fetchPendingList(page, searchTerm, priorityFilter, dateFilter);
  };
  
  // Refresh data
  const refreshData = () => {
    fetchPendingList(currentPage, searchTerm, priorityFilter, dateFilter);
  };
  
  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
                <Clock className="h-8 w-8 text-orange-600" />
                B2B PO Pending
              </h1>
              <p className="text-gray-600 mt-2">Review and approve pending purchase orders</p>
            </div>
            <div className="flex items-center gap-4">
              <button
                onClick={refreshData}
                className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 flex items-center gap-2"
              >
                <RefreshCw className="h-4 w-4" />
                Refresh
              </button>
              <div className="text-sm text-gray-500">
                Logged in as: <span className="font-semibold text-gray-700">{user?.username}</span>
              </div>
            </div>
          </div>
        </div>
        
        {/* Tabs */}
        <div className="mb-6">
          <div className="border-b border-gray-200">
            <nav className="-mb-px flex space-x-8">
              <button
                onClick={() => setActiveTab('pending')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'pending'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Clock className="h-4 w-4 inline mr-2" />
                Pending Review
              </button>
              <button
                onClick={() => setActiveTab('management')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'management'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Package className="h-4 w-4 inline mr-2" />
                Pending Management
              </button>
            </nav>
          </div>
        </div>
        
        {/* Pending Review Tab */}
        {activeTab === 'pending' && (
          <div className="space-y-6">
            {/* Status Check Form */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
                <Zap className="h-5 w-5 text-green-600" />
                Check PO Status
              </h2>
              
              <form onSubmit={(e) => { e.preventDefault(); checkPOStatus(poNumber); }} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      PO Number
                    </label>
                    <input
                      ref={poNumberInputRef}
                      type="text"
                      value={poNumber}
                      onChange={(e) => setPONumber(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      placeholder="Enter PO number to check status"
                      disabled={statusLoading}
                    />
                  </div>
                  <div className="flex items-end">
                    <button
                      type="submit"
                      disabled={statusLoading || !poNumber.trim()}
                      className="w-full bg-gray-600 text-white px-4 py-2 rounded-md hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                      {statusLoading ? (
                        <Clock className="h-4 w-4 animate-spin" />
                      ) : (
                        <Eye className="h-4 w-4" />
                      )}
                      Check Status
                    </button>
                  </div>
                </div>
              </form>
              
              {/* Current PO Status Display */}
              {currentPOStatus && (
                <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-md">
                  <h3 className="text-sm font-medium text-blue-900 mb-2">Current PO Status:</h3>
                  <pre className="text-sm text-blue-800 whitespace-pre-wrap">{JSON.stringify(currentPOStatus, null, 2)}</pre>
                </div>
              )}
            </div>
          </div>
        )}
        
        {/* Pending Management Tab */}
        {activeTab === 'management' && (
          <div className="space-y-6">
            {/* Search and Filters */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
                <Search className="h-5 w-5 text-blue-600" />
                Pending Orders
              </h2>
              
              {/* Bulk Actions */}
              <div className="mb-4 flex gap-2">
                <button
                  onClick={selectAllPOs}
                  className="bg-gray-600 text-white px-3 py-1 rounded-md hover:bg-gray-700 text-sm"
                >
                  Select All
                </button>
                <button
                  onClick={deselectAllPOs}
                  className="bg-gray-600 text-white px-3 py-1 rounded-md hover:bg-gray-700 text-sm"
                >
                  Deselect All
                </button>
                <button
                  onClick={() => handleBulkApproval('approve')}
                  disabled={approvalLoading}
                  className="bg-green-600 text-white px-3 py-1 rounded-md hover:bg-green-700 text-sm disabled:opacity-50"
                >
                  Approve Selected
                </button>
                <button
                  onClick={() => handleBulkApproval('reject')}
                  disabled={approvalLoading}
                  className="bg-red-600 text-white px-3 py-1 rounded-md hover:bg-red-700 text-sm disabled:opacity-50"
                >
                  Reject Selected
                </button>
              </div>
              
              {/* Search and Filter Form */}
              <form onSubmit={handleSearch} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Search by PO number, customer..."
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <select
                    value={priorityFilter}
                    onChange={(e) => {
                      setPriorityFilter(e.target.value);
                      handleFilterChange();
                    }}
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">All Priority</option>
                    <option value="high">High Priority</option>
                    <option value="medium">Medium Priority</option>
                    <option value="low">Low Priority</option>
                  </select>
                  <input
                    type="date"
                    value={dateFilter}
                    onChange={(e) => {
                      setDateFilter(e.target.value);
                      handleFilterChange();
                    }}
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <button
                    type="submit"
                    className="bg-gray-600 text-white px-4 py-2 rounded-md hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 flex items-center justify-center gap-2"
                  >
                    <Search className="h-4 w-4" />
                    Search
                  </button>
                </div>
              </form>
            </div>
            
            {/* Pending List */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200">
              {pendingListLoading ? (
                <div className="p-8 text-center">
                  <Clock className="h-8 w-8 animate-spin mx-auto text-gray-400" />
                  <p className="text-gray-500 mt-2">Loading pending orders...</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                          <input
                            type="checkbox"
                            onChange={(e) => e.target.checked ? selectAllPOs() : deselectAllPOs()}
                            className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                          />
                        </th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">PO Number</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Customer</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Amount</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Priority</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Created Date</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {pendingList.map((po) => (
                        <tr key={po.id} className="hover:bg-gray-50">
                          <td className="px-6 py-4 whitespace-nowrap">
                            <input
                              type="checkbox"
                              checked={po.selected || false}
                              onChange={() => togglePOSelection(po.id)}
                              className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                            />
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                            {po.po_number}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {po.customer_name}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {po.currency} {po.total_amount}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                              po.priority === 'high' ? 'bg-red-100 text-red-800' :
                              po.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                              po.priority === 'low' ? 'bg-green-100 text-green-800' :
                              'bg-gray-100 text-gray-800'
                            }`}>
                              {po.priority}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {new Date(po.created_at).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                              po.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                              po.status === 'approved' ? 'bg-green-100 text-green-800' :
                              po.status === 'rejected' ? 'bg-red-100 text-red-800' :
                              'bg-gray-100 text-gray-800'
                            }`}>
                              {po.status}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                            <div className="flex gap-2">
                              <button
                                onClick={() => handlePOApproval(po.id, 'approve')}
                                disabled={approvalLoading}
                                className="text-green-600 hover:text-green-900 disabled:opacity-50"
                                title="Approve PO"
                              >
                                <CheckCircle className="h-4 w-4" />
                              </button>
                              <button
                                onClick={() => {
                                  setSelectedPO(po);
                                  setShowRejectionModal(true);
                                }}
                                disabled={approvalLoading}
                                className="text-red-600 hover:text-red-900 disabled:opacity-50"
                                title="Reject PO"
                              >
                                <XCircle className="h-4 w-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  
                  {pendingList.length === 0 && (
                    <div className="p-8 text-center text-gray-500">
                      No pending orders found
                    </div>
                  )}
                </div>
              )}
              
              {/* Pagination */}
              {totalPages > 1 && (
                <div className="px-6 py-3 border-t border-gray-200 flex items-center justify-between">
                  <div className="text-sm text-gray-700">
                    Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, totalItems)} of {totalItems} results
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage === 1}
                      className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Previous
                    </button>
                    <span className="px-3 py-1 text-sm text-gray-700">
                      Page {currentPage} of {totalPages}
                    </span>
                    <button
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={currentPage === totalPages}
                      className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Next
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
        
        {/* Rejection Modal */}
        {showRejectionModal && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-lg max-w-md w-full">
              <div className="p-6">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">
                    Reject Purchase Order
                  </h3>
                  <button
                    onClick={() => setShowRejectionModal(false)}
                    className="text-gray-400 hover:text-gray-600"
                  >
                    <XCircle className="h-6 w-6" />
                  </button>
                </div>
                
                <div className="mb-4">
                  <p className="text-sm text-gray-600 mb-2">
                    PO Number: <span className="font-semibold">{selectedPO?.po_number}</span>
                  </p>
                  <p className="text-sm text-gray-600">
                    Customer: <span className="font-semibold">{selectedPO?.customer_name}</span>
                  </p>
                </div>
                
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Rejection Reason *
                  </label>
                  <textarea
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="Enter reason for rejection..."
                    required
                  />
                </div>
                
                <div className="flex justify-end gap-4">
                  <button
                    onClick={() => setShowRejectionModal(false)}
                    className="px-4 py-2 text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={() => handlePOApproval(selectedPO.id, 'reject')}
                    disabled={approvalLoading || !rejectionReason.trim()}
                    className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {approvalLoading ? 'Rejecting...' : 'Reject PO'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default B2BPOPending;
