import React, { useState, useEffect, useRef } from 'react';
import { Truck, CheckCircle, XCircle, Clock, Search, Package, Zap, Eye, Filter, Download, FileText, Calendar, MapPin, DollarSign, Users, Box } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAuthStore } from '../stores/authStore';
import { scanAPI, adminAPI, gcsAPI } from '../services/api';
import { playSuccessSound, playErrorSound } from '../utils/soundUtils';

const B2BPODispatch = () => {
  const { user } = useAuthStore();
  const [activeTab, setActiveTab] = useState('dispatch');
  
  // Dispatch State
  const [poNumber, setPONumber] = useState('');
  const [dispatchLoading, setDispatchLoading] = useState(false);
  const [currentPOStatus, setCurrentPOStatus] = useState('');
  const [statusLoading, setStatusLoading] = useState(false);
  
  // Dispatch List State
  const [dispatchList, setDispatchList] = useState([]);
  const [dispatchListLoading, setDispatchListLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [dateFilter, setDateFilter] = useState('');
  
  // Courier Management State
  const [courierList, setCourierList] = useState([]);
  const [selectedCourier, setSelectedCourier] = useState('');
  const [trackingNumber, setTrackingNumber] = useState('');
  const [courierLoading, setCourierLoading] = useState(false);
  
  // Dispatch PO Data Viewing State
  const [dispatchPONumber, setDispatchPONumber] = useState('');
  const [dispatchPOData, setDispatchPOData] = useState(null);
  const [dispatchPOLoading, setDispatchPOLoading] = useState(false);
  const [dispatchPOError, setDispatchPOError] = useState('');
  
  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);
  const itemsPerPage = 20;
  
  // Refs for input focus
  const poNumberInputRef = useRef(null);
  
  // Set document title
  useEffect(() => {
    document.title = 'B2B PO Dispatch - OneScan';
  }, []);
  
  // Focus on input when component mounts
  useEffect(() => {
    if (poNumberInputRef.current) {
      poNumberInputRef.current.focus();
    }
  }, [activeTab]);
  
  // Fetch dispatch list
  const fetchDispatchList = async (page = 1, search = '', status = 'all', date = '') => {
    try {
      setDispatchListLoading(true);
      const params = new URLSearchParams({
        page: page.toString(),
        limit: itemsPerPage.toString(),
        search: search,
        status: status,
        date: date
      });
      
      const response = await adminAPI.get(`/b2b/dispatch?${params}`);
      
      setDispatchList(response.data.dispatches || []);
      setTotalPages(response.data.total_pages || 1);
      setTotalItems(response.data.total_items || 0);
    } catch (error) {
      console.error('Error fetching dispatch list:', error);
      toast.error('Failed to fetch dispatch records');
    } finally {
      setDispatchListLoading(false);
    }
  };
  
  // Fetch courier list
  const fetchCourierList = async () => {
    try {
      const response = await adminAPI.get('/b2b/couriers');
      setCourierList(response.data.couriers || []);
    } catch (error) {
      console.error('Error fetching courier list:', error);
      toast.error('Failed to fetch courier list');
    }
  };
  
  // Handle PO dispatch
  const handlePODispatch = async (e) => {
    e.preventDefault();
    
    if (!poNumber.trim()) {
      toast.error('Please enter a PO number');
      return;
    }
    
    if (!selectedCourier) {
      toast.error('Please select a courier');
      return;
    }
    
    if (!trackingNumber.trim()) {
      toast.error('Please enter a tracking number');
      return;
    }
    
    try {
      setDispatchLoading(true);
      const response = await scanAPI.post('/b2b/dispatch-po', {
        po_number: poNumber.trim(),
        courier_id: selectedCourier,
        tracking_number: trackingNumber.trim(),
        dispatched_by: user.username,
        dispatched_at: new Date().toISOString()
      });
      
      if (response.data.success) {
        toast.success('PO dispatched successfully!');
        playSuccessSound();
        setPONumber('');
        setSelectedCourier('');
        setTrackingNumber('');
        fetchDispatchList(currentPage, searchTerm, statusFilter, dateFilter);
      } else {
        toast.error(response.data.message || 'Failed to dispatch PO');
        playErrorSound();
      }
    } catch (error) {
      console.error('Error dispatching PO:', error);
      toast.error(error.response?.data?.detail || error.message || 'Failed to dispatch PO');
      playErrorSound();
    } finally {
      setDispatchLoading(false);
    }
  };
  
  // Check PO status
  const checkPOStatus = async (poNumber) => {
    if (!poNumber.trim()) {
      toast.error('Please enter a PO number');
      return;
    }
    
    try {
      setStatusLoading(true);
      const response = await scanAPI.get(`/b2b/po-status/${poNumber.trim()}`);
      
      if (response.data) {
        setCurrentPOStatus(response.data);
        toast.success('PO status retrieved');
      } else {
        toast.error('PO not found');
      }
    } catch (error) {
      console.error('Error checking PO status:', error);
      toast.error(error.response?.data?.detail || error.message || 'Failed to check PO status');
    } finally {
      setStatusLoading(false);
    }
  };
  
  // Update dispatch status
  const updateDispatchStatus = async (dispatchId, newStatus) => {
    try {
      const response = await adminAPI.put(`/b2b/dispatch/${dispatchId}/status`, {
        status: newStatus,
        updated_by: user.username
      });
      
      toast.success('Dispatch status updated successfully');
      fetchDispatchList(currentPage, searchTerm, statusFilter, dateFilter);
    } catch (error) {
      console.error('Error updating dispatch status:', error);
      toast.error(error.response?.data?.detail || error.message || 'Failed to update dispatch status');
    }
  };
  
  // Export dispatch data
  const exportDispatchData = async () => {
    try {
      const response = await adminAPI.get('/b2b/dispatch/export', {
        responseType: 'blob'
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `dispatch_data_${new Date().toISOString().split('T')[0]}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
      
      toast.success('Dispatch data exported successfully');
    } catch (error) {
      console.error('Error exporting dispatch data:', error);
      toast.error('Failed to export dispatch data');
    }
  };
  
  // Fetch dispatch PO data
  const fetchDispatchPOData = async (poNumber) => {
    if (!poNumber.trim()) {
      toast.error('Please enter a PO number');
      return;
    }
    
    try {
      setDispatchPOLoading(true);
      setDispatchPOError('');
      
      const response = await gcsAPI.getDispatchPOData(poNumber.trim());
      
      if (response.data.ok) {
        setDispatchPOData(response.data.data);
        toast.success('Dispatch PO data retrieved successfully');
        playSuccessSound();
      } else {
        setDispatchPOError(response.data.message || 'Failed to retrieve dispatch PO data');
        toast.error(response.data.message || 'Failed to retrieve dispatch PO data');
        playErrorSound();
      }
    } catch (error) {
      console.error('Error fetching dispatch PO data:', error);
      const errorMessage = error.response?.data?.detail || error.message || 'Failed to fetch dispatch PO data';
      setDispatchPOError(errorMessage);
      toast.error(errorMessage);
      playErrorSound();
    } finally {
      setDispatchPOLoading(false);
    }
  };
  
  // Load data on component mount
  useEffect(() => {
    fetchDispatchList();
    fetchCourierList();
  }, []);
  
  // Handle search
  const handleSearch = (e) => {
    e.preventDefault();
    setCurrentPage(1);
    fetchDispatchList(1, searchTerm, statusFilter, dateFilter);
  };
  
  // Handle filter change
  const handleFilterChange = () => {
    setCurrentPage(1);
    fetchDispatchList(1, searchTerm, statusFilter, dateFilter);
  };
  
  // Handle page change
  const handlePageChange = (page) => {
    setCurrentPage(page);
    fetchDispatchList(page, searchTerm, statusFilter, dateFilter);
  };
  
  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
                <Truck className="h-8 w-8 text-blue-600" />
                B2B PO Dispatch
              </h1>
              <p className="text-gray-600 mt-2">Manage and dispatch purchase orders to customers</p>
            </div>
            <div className="flex items-center gap-4">
              <button
                onClick={exportDispatchData}
                className="bg-green-600 text-white px-4 py-2 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 flex items-center gap-2"
              >
                <Download className="h-4 w-4" />
                Export Data
              </button>
              <div className="text-sm text-gray-500">
                Logged in as: <span className="font-semibold text-gray-700">{user?.username}</span>
              </div>
            </div>
          </div>
        </div>
        
        {/* Tabs */}
        <div className="mb-6">
          <div className="border-b border-gray-200">
            <nav className="-mb-px flex space-x-8">
              <button
                onClick={() => setActiveTab('dispatch')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'dispatch'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Truck className="h-4 w-4 inline mr-2" />
                Dispatch PO
              </button>
              <button
                onClick={() => setActiveTab('view-dispatch')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'view-dispatch'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <FileText className="h-4 w-4 inline mr-2" />
                View Dispatch Data
              </button>
              <button
                onClick={() => setActiveTab('management')}
                className={`py-2 px-1 border-b-2 font-medium text-sm ${
                  activeTab === 'management'
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <Package className="h-4 w-4 inline mr-2" />
                Dispatch Management
              </button>
            </nav>
          </div>
        </div>
        
        {/* Dispatch Tab */}
        {activeTab === 'dispatch' && (
          <div className="space-y-6">
            {/* Dispatch Form */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
                <Zap className="h-5 w-5 text-green-600" />
                Dispatch Purchase Order
              </h2>
              
              <form onSubmit={handlePODispatch} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      PO Number *
                    </label>
                    <input
                      ref={poNumberInputRef}
                      type="text"
                      value={poNumber}
                      onChange={(e) => setPONumber(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      placeholder="Enter PO number to dispatch"
                      disabled={dispatchLoading}
                    />
                  </div>
                  <div className="flex items-end">
                    <button
                      type="button"
                      onClick={() => checkPOStatus(poNumber)}
                      disabled={statusLoading || !poNumber.trim()}
                      className="w-full bg-gray-600 text-white px-4 py-2 rounded-md hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                      {statusLoading ? (
                        <Clock className="h-4 w-4 animate-spin" />
                      ) : (
                        <Eye className="h-4 w-4" />
                      )}
                      Check Status
                    </button>
                  </div>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Courier *
                    </label>
                    <select
                      value={selectedCourier}
                      onChange={(e) => setSelectedCourier(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      disabled={dispatchLoading}
                    >
                      <option value="">Select Courier</option>
                      {courierList.map((courier) => (
                        <option key={courier.id} value={courier.id}>
                          {courier.name} - {courier.service_type}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Tracking Number *
                    </label>
                    <input
                      type="text"
                      value={trackingNumber}
                      onChange={(e) => setTrackingNumber(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      placeholder="Enter tracking number"
                      disabled={dispatchLoading}
                    />
                  </div>
                </div>
                
                <div className="flex gap-4">
                  <button
                    type="submit"
                    disabled={dispatchLoading || !poNumber.trim() || !selectedCourier || !trackingNumber.trim()}
                    className="bg-green-600 text-white px-6 py-2 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                  >
                    {dispatchLoading ? (
                      <Clock className="h-4 w-4 animate-spin" />
                    ) : (
                      <CheckCircle className="h-4 w-4" />
                    )}
                    Dispatch PO
                  </button>
                </div>
              </form>
              
              {/* Current PO Status Display */}
              {currentPOStatus && (
                <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-md">
                  <h3 className="text-sm font-medium text-blue-900 mb-2">Current PO Status:</h3>
                  <pre className="text-sm text-blue-800 whitespace-pre-wrap">{JSON.stringify(currentPOStatus, null, 2)}</pre>
                </div>
              )}
            </div>
          </div>
        )}
        
        {/* View Dispatch Data Tab */}
        {activeTab === 'view-dispatch' && (
          <div className="space-y-6">
            {/* Dispatch PO Data Search */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
                <FileText className="h-5 w-5 text-blue-600" />
                View Dispatch PO Data
              </h2>
              
              <div className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      PO Number *
                    </label>
                    <input
                      type="text"
                      value={dispatchPONumber}
                      onChange={(e) => setDispatchPONumber(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                      placeholder="Enter PO number to view dispatch data"
                      disabled={dispatchPOLoading}
                    />
                  </div>
                  <div className="flex items-end">
                    <button
                      onClick={() => fetchDispatchPOData(dispatchPONumber)}
                      disabled={dispatchPOLoading || !dispatchPONumber.trim()}
                      className="w-full bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                      {dispatchPOLoading ? (
                        <Clock className="h-4 w-4 animate-spin" />
                      ) : (
                        <Search className="h-4 w-4" />
                      )}
                      View Data
                    </button>
                  </div>
                </div>
                
                {dispatchPOError && (
                  <div className="p-4 bg-red-50 border border-red-200 rounded-md">
                    <p className="text-sm text-red-800">{dispatchPOError}</p>
                  </div>
                )}
              </div>
            </div>
            
            {/* Dispatch PO Data Display */}
            {dispatchPOData && (
              <div className="space-y-6">
                {/* PO Overview */}
                <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                    <Package className="h-5 w-5 text-green-600" />
                    PO Overview
                  </h3>
                  
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div className="bg-blue-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <FileText className="h-8 w-8 text-blue-600" />
                        <div className="ml-3">
                          <p className="text-sm font-medium text-blue-900">PO Number</p>
                          <p className="text-lg font-semibold text-blue-800">{dispatchPOData.po_number}</p>
                        </div>
                      </div>
                    </div>
                    
                    <div className="bg-green-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <MapPin className="h-8 w-8 text-green-600" />
                        <div className="ml-3">
                          <p className="text-sm font-medium text-green-900">Platform</p>
                          <p className="text-lg font-semibold text-green-800">{dispatchPOData.platform}</p>
                        </div>
                      </div>
                    </div>
                    
                    <div className="bg-purple-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <Calendar className="h-8 w-8 text-purple-600" />
                        <div className="ml-3">
                          <p className="text-sm font-medium text-purple-900">PO Date</p>
                          <p className="text-lg font-semibold text-purple-800">{dispatchPOData.po_date}</p>
                        </div>
                      </div>
                    </div>
                    
                    <div className="bg-orange-50 p-4 rounded-lg">
                      <div className="flex items-center">
                        <DollarSign className="h-8 w-8 text-orange-600" />
                        <div className="ml-3">
                          <p className="text-sm font-medium text-orange-900">Currency</p>
                          <p className="text-lg font-semibold text-orange-800">{dispatchPOData.currency}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                  
                  <div className="mt-4 grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="text-sm font-medium text-gray-700">Location</p>
                      <p className="text-lg font-semibold text-gray-900">{dispatchPOData.location}</p>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="text-sm font-medium text-gray-700">Status</p>
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        dispatchPOData.status === 'dispatched' ? 'bg-green-100 text-green-800' :
                        dispatchPOData.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                        dispatchPOData.status === 'approved' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {dispatchPOData.status}
                      </span>
                    </div>
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <p className="text-sm font-medium text-gray-700">Items Count</p>
                      <p className="text-lg font-semibold text-gray-900">{dispatchPOData.items_count}</p>
                    </div>
                  </div>
                </div>
                
                {/* Dispatch Information */}
                {dispatchPOData.dispatch_data && (
                  <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                      <Truck className="h-5 w-5 text-blue-600" />
                      Dispatch Information
                    </h3>
                    
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                      <div className="bg-blue-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-blue-700">Dispatch ID</p>
                        <p className="text-sm font-semibold text-blue-900">{dispatchPOData.dispatch_data.dispatch_id}</p>
                      </div>
                      
                      <div className="bg-green-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-green-700">Courier</p>
                        <p className="text-sm font-semibold text-green-900">{dispatchPOData.dispatch_data.courier}</p>
                      </div>
                      
                      <div className="bg-purple-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-purple-700">Dispatch Date</p>
                        <p className="text-sm font-semibold text-purple-900">{dispatchPOData.dispatch_data.dispatch_date}</p>
                      </div>
                      
                      <div className="bg-orange-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-orange-700">Dispatched By</p>
                        <p className="text-sm font-semibold text-orange-900">{dispatchPOData.dispatch_data.dispatched_by}</p>
                      </div>
                      
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-gray-700">Vehicle Number</p>
                        <p className="text-sm font-semibold text-gray-900">{dispatchPOData.dispatch_data.vehicle_no || 'N/A'}</p>
                      </div>
                      
                      <div className="bg-gray-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-gray-700">Waybill Number</p>
                        <p className="text-sm font-semibold text-gray-900">{dispatchPOData.dispatch_data.waybill_no || 'N/A'}</p>
                      </div>
                    </div>
                    
                    {dispatchPOData.dispatch_data.notes && (
                      <div className="mt-4 bg-yellow-50 p-4 rounded-lg">
                        <p className="text-sm font-medium text-yellow-700">Notes</p>
                        <p className="text-sm text-yellow-900">{dispatchPOData.dispatch_data.notes}</p>
                      </div>
                    )}
                  </div>
                )}
                
                {/* Items Information */}
                {dispatchPOData.po_data && dispatchPOData.po_data.items && (
                  <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                    <div className="px-6 py-4 border-b border-gray-200">
                      <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                        <Box className="h-5 w-5 text-green-600" />
                        PO Items ({dispatchPOData.po_data.items.length})
                      </h3>
                    </div>
                    
                    <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                          <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">SKU</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">G-Code</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">EAN</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Unit Price</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Total Price</th>
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {dispatchPOData.po_data.items.map((item, index) => (
                            <tr key={index} className="hover:bg-gray-50">
                              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                {item.sku}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                {item.g_code || 'N/A'}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                {item.ean || 'N/A'}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                {item.quantity}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                {item.unit_price ? `${dispatchPOData.currency} ${item.unit_price}` : 'N/A'}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                {item.total_price ? `${dispatchPOData.currency} ${item.total_price}` : 'N/A'}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
                
                {/* Planning Information */}
                {dispatchPOData.po_data && dispatchPOData.po_data.planning_items && dispatchPOData.po_data.planning_items.length > 0 && (
                  <div className="bg-white rounded-lg shadow-sm border border-gray-200">
                    <div className="px-6 py-4 border-b border-gray-200">
                      <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                        <Users className="h-5 w-5 text-blue-600" />
                        Planning Information ({dispatchPOData.po_data.planning_items.length})
                      </h3>
                    </div>
                    
                    <div className="p-6">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                        <div className="bg-blue-50 p-4 rounded-lg">
                          <p className="text-sm font-medium text-blue-700">Planned Quantity Total</p>
                          <p className="text-lg font-semibold text-blue-900">{dispatchPOData.planned_qty_total}</p>
                        </div>
                        <div className="bg-green-50 p-4 rounded-lg">
                          <p className="text-sm font-medium text-green-700">Planned Amount Total</p>
                          <p className="text-lg font-semibold text-green-900">{dispatchPOData.currency} {dispatchPOData.planned_amount_total}</p>
                        </div>
                      </div>
                      
                      <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-200">
                          <thead className="bg-gray-50">
                            <tr>
                              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">SKU</th>
                              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Planned Qty</th>
                              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Selected</th>
                            </tr>
                          </thead>
                          <tbody className="bg-white divide-y divide-gray-200">
                            {dispatchPOData.po_data.planning_items.map((item, index) => (
                              <tr key={index} className="hover:bg-gray-50">
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                  {item.sku}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                  {item.quantity}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                  {item.planned_qty || 'N/A'}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap">
                                  <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                                    item.selected_for_planning ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'
                                  }`}>
                                    {item.selected_for_planning ? 'Yes' : 'No'}
                                  </span>
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                )}
                
                {/* Files Information */}
                {dispatchPOData.po_data && dispatchPOData.po_data.uploaded_files && dispatchPOData.po_data.uploaded_files.length > 0 && (
                  <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
                      <FileText className="h-5 w-5 text-purple-600" />
                      Uploaded Files ({dispatchPOData.po_data.uploaded_files.length})
                    </h3>
                    
                    <div className="space-y-2">
                      {dispatchPOData.po_data.uploaded_files.map((file, index) => (
                        <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                          <div className="flex items-center">
                            <FileText className="h-5 w-5 text-gray-400 mr-3" />
                            <div>
                              <p className="text-sm font-medium text-gray-900">{file.name}</p>
                              <p className="text-xs text-gray-500">{file.type} • {(file.size / 1024).toFixed(1)} KB</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <a
                              href={file.serve_url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                            >
                              View
                            </a>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
        
        {/* Dispatch Management Tab */}
        {activeTab === 'management' && (
          <div className="space-y-6">
            {/* Search and Filters */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center gap-2">
                <Search className="h-5 w-5 text-blue-600" />
                Dispatch Records
              </h2>
              
              {/* Search and Filter Form */}
              <form onSubmit={handleSearch} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Search by PO number, tracking number..."
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <select
                    value={statusFilter}
                    onChange={(e) => {
                      setStatusFilter(e.target.value);
                      handleFilterChange();
                    }}
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    <option value="all">All Status</option>
                    <option value="dispatched">Dispatched</option>
                    <option value="in_transit">In Transit</option>
                    <option value="delivered">Delivered</option>
                    <option value="failed">Failed</option>
                    <option value="returned">Returned</option>
                  </select>
                  <input
                    type="date"
                    value={dateFilter}
                    onChange={(e) => {
                      setDateFilter(e.target.value);
                      handleFilterChange();
                    }}
                    className="px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <button
                    type="submit"
                    className="bg-gray-600 text-white px-4 py-2 rounded-md hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 flex items-center justify-center gap-2"
                  >
                    <Search className="h-4 w-4" />
                    Search
                  </button>
                </div>
              </form>
            </div>
            
            {/* Dispatch List */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200">
              {dispatchListLoading ? (
                <div className="p-8 text-center">
                  <Clock className="h-8 w-8 animate-spin mx-auto text-gray-400" />
                  <p className="text-gray-500 mt-2">Loading dispatch records...</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">PO Number</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Customer</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Courier</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tracking</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Dispatch Date</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {dispatchList.map((dispatch) => (
                        <tr key={dispatch.id} className="hover:bg-gray-50">
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                            {dispatch.po_number}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {dispatch.customer_name}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {dispatch.courier_name}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {dispatch.tracking_number}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {new Date(dispatch.dispatched_at).toLocaleDateString()}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                              dispatch.status === 'delivered' ? 'bg-green-100 text-green-800' :
                              dispatch.status === 'in_transit' ? 'bg-blue-100 text-blue-800' :
                              dispatch.status === 'dispatched' ? 'bg-yellow-100 text-yellow-800' :
                              dispatch.status === 'failed' ? 'bg-red-100 text-red-800' :
                              dispatch.status === 'returned' ? 'bg-orange-100 text-orange-800' :
                              'bg-gray-100 text-gray-800'
                            }`}>
                              {dispatch.status}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                            <div className="flex gap-2">
                              {dispatch.status === 'dispatched' && (
                                <button
                                  onClick={() => updateDispatchStatus(dispatch.id, 'in_transit')}
                                  className="text-blue-600 hover:text-blue-900"
                                  title="Mark as In Transit"
                                >
                                  <Truck className="h-4 w-4" />
                                </button>
                              )}
                              {dispatch.status === 'in_transit' && (
                                <button
                                  onClick={() => updateDispatchStatus(dispatch.id, 'delivered')}
                                  className="text-green-600 hover:text-green-900"
                                  title="Mark as Delivered"
                                >
                                  <CheckCircle className="h-4 w-4" />
                                </button>
                              )}
                              {(dispatch.status === 'dispatched' || dispatch.status === 'in_transit') && (
                                <button
                                  onClick={() => updateDispatchStatus(dispatch.id, 'failed')}
                                  className="text-red-600 hover:text-red-900"
                                  title="Mark as Failed"
                                >
                                  <XCircle className="h-4 w-4" />
                                </button>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  
                  {dispatchList.length === 0 && (
                    <div className="p-8 text-center text-gray-500">
                      No dispatch records found
                    </div>
                  )}
                </div>
              )}
              
              {/* Pagination */}
              {totalPages > 1 && (
                <div className="px-6 py-3 border-t border-gray-200 flex items-center justify-between">
                  <div className="text-sm text-gray-700">
                    Showing {((currentPage - 1) * itemsPerPage) + 1} to {Math.min(currentPage * itemsPerPage, totalItems)} of {totalItems} results
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage === 1}
                      className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Previous
                    </button>
                    <span className="px-3 py-1 text-sm text-gray-700">
                      Page {currentPage} of {totalPages}
                    </span>
                    <button
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={currentPage === totalPages}
                      className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Next
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default B2BPODispatch;
